INSERT IGNORE INTO configuracion (clave, valor, tipo, descripcion) VALUES ('terminos_condiciones', '["Oferta válida por 15 días. Precios sujetos a cambios por fluctuación de moneda o inventario.","Esta propuesta incluye únicamente los equipos y servicios descritos. Obras civiles o adecuaciones no especificadas tendrán costo adicional.","Los trámites de legalización no dependen directamente de la empresa, ya que son gestionados ante entidades externas y autónomas.","La empresa no asume responsabilidad por demoras, suspensiones o negativas por parte de la UPME, el RETIE o el Operador de Red","Anticipo del 60% para iniciar, pagos contra avance y saldo contra entrega de la planta totalmente funcional.","Los plazos estimados pueden verse afectados por demoras en trámites externos, importaciones o casos de fuerza mayor.","Aplica garantía de 5 años por defectos de fábrica para equipos y de 1 año para la instalación (sujeta a un uso adecuado y sin intervenciones de terceros)."]', 'string', NULL);
